mapper.insert:
INSERT INTO CMP_COMP_INFO_TBL (
	COMP_CD
  , COMP_TP
  , SUBSCR_STAT_TP
  , CNTRCT_STAT_TP
  , USE_YN
  , BRN
  , COMP_NM
  , COMP_DISP_NM
  , COMP_DESC
  , COMP_TEL_NO
  , COMP_ZIP_CD
  , COMP_ADDR
  , COMP_DTL_ADDR
  , COMP_LOC 
  , RPRSNTV_NM
  , RPRSNTV_EMAL_ADDR
  , RPRSNTV_MBL_NO
  , RGST_DT
  , RGST_SEQ
)
VALUES (
	#{compCd, jdbcType=VARCHAR}
  , 	#{compTp, jdbcType=VARCHAR}			
  , 	#{subscrStatTp, jdbcType=VARCHAR}
  , 	#{cntrctStatTp, jdbcType=VARCHAR}
  , 	#{useYn, jdbcType=VARCHAR}
  , 	#{brn, jdbcType=VARCHAR}
  , 	#{compNm, jdbcType=VARCHAR}
  , 	#{compDispNm, jdbcType=VARCHAR}
  , 	#{compDesc, jdbcType=VARCHAR}
  , 	#{compTelNo, jdbcType=VARCHAR}
  , 	#{compZipCd, jdbcType=VARCHAR}
  , 	#{compAddr, jdbcType=VARCHAR}
  , 	#{compDtlAddr, jdbcType=VARCHAR}
  , #{compLoc, jdbcType=VARCHAR}
  , 	#{rprsntvNm, jdbcType=VARCHAR}
  , 	#{rprsntvEmalAddr, jdbcType=VARCHAR}
  , 	#{rprsntvMblNo, jdbcType=VARCHAR}
  , 	CURRENT_TIMESTAMP(3)
  , 	#{rgstSeq, jdbcType=NUMERIC}
)

mapper.update:
		UPDATE CMP_COMP_INFO_TBL
		SET 	COMP_TP  = (
					CASE
						WHEN (#{compTp, jdbcType=VARCHAR} IS NULL OR #{compTp, jdbcType=VARCHAR} = '') THEN COMP_TP
						ELSE   #{compTp, jdbcType=VARCHAR}
					END
				)
			  , SUBSCR_STAT_TP = (
					CASE
						WHEN (#{subscrStatTp, jdbcType=VARCHAR} IS NULL OR #{subscrStatTp, jdbcType=VARCHAR} = '') THEN SUBSCR_STAT_TP
						ELSE   #{subscrStatTp, jdbcType=VARCHAR}
					END 
			  	)
			  , CNTRCT_STAT_TP = (
					CASE
						WHEN (#{cntrctStatTp, jdbcType=VARCHAR} IS NULL OR #{cntrctStatTp, jdbcType=VARCHAR} = '') THEN CNTRCT_STAT_TP
						ELSE   #{cntrctStatTp, jdbcType=VARCHAR}
					END 
			  	)
			  , USE_YN = (
					CASE
						WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN USE_YN
						ELSE   #{useYn, jdbcType=VARCHAR}
					END 
			  	)
			  , COMP_NM = (
					CASE
						WHEN (#{compNm, jdbcType=VARCHAR} IS NULL OR #{compNm, jdbcType=VARCHAR} = '') THEN COMP_NM
						ELSE   #{compNm, jdbcType=VARCHAR}
					END
			  	)
			  , COMP_DISP_NM = (
					CASE
						WHEN (#{compDispNm, jdbcType=VARCHAR} IS NULL OR #{compDispNm, jdbcType=VARCHAR} = '') THEN COMP_DISP_NM
						ELSE   #{compDispNm, jdbcType=VARCHAR}
					END
			  	)
			  , COMP_DESC = (
					CASE
						WHEN (#{compDesc, jdbcType=VARCHAR} IS NULL OR #{compDesc, jdbcType=VARCHAR} = '') THEN COMP_DESC
						ELSE   #{compDesc, jdbcType=VARCHAR}
					END	
			  	)
			  , COMP_TEL_NO = (
					CASE
						WHEN (#{compTelNo, jdbcType=VARCHAR} IS NULL OR #{compTelNo, jdbcType=VARCHAR} = '') THEN COMP_TEL_NO
						ELSE   #{compTelNo, jdbcType=VARCHAR}
					END	
			  	)
			  , COMP_ZIP_CD = (
				 	CASE
						WHEN (#{compZipCd, jdbcType=VARCHAR} IS NULL OR #{compZipCd, jdbcType=VARCHAR} = '') THEN COMP_ZIP_CD
						ELSE   #{compZipCd, jdbcType=VARCHAR}
					END	
			  	)
			  , COMP_ADDR = (
					CASE
						WHEN (#{compAddr, jdbcType=VARCHAR} IS NULL OR #{compAddr, jdbcType=VARCHAR} = '') THEN COMP_ADDR
						ELSE   #{compAddr, jdbcType=VARCHAR}
					END	
			  	)
			  , COMP_DTL_ADDR = (
					CASE
						WHEN (#{compDtlAddr, jdbcType=VARCHAR} IS NULL OR #{compDtlAddr, jdbcType=VARCHAR} = '') THEN COMP_DTL_ADDR
						ELSE   #{compDtlAddr, jdbcType=VARCHAR}
					END
			  	)
			  , COMP_LOC = (
					CASE
						WHEN (#{compLoc, jdbcType=VARCHAR} IS NULL OR #{compLoc, jdbcType=VARCHAR} = '') THEN COMP_LOC
						ELSE   #{compLoc, jdbcType=VARCHAR}
					END	
			  	)
			  , RPRSNTV_NM = (
					CASE	
						WHEN (#{rprsntvNm, jdbcType=VARCHAR} IS NULL OR #{rprsntvNm, jdbcType=VARCHAR} = '') THEN RPRSNTV_NM
						ELSE   #{rprsntvNm, jdbcType=VARCHAR}
					END	
			  	)
			  , RPRSNTV_EMAL_ADDR = (
					CASE
						WHEN (#{rprsntvEmalAddr, jdbcType=VARCHAR} IS NULL OR #{rprsntvEmalAddr, jdbcType=VARCHAR} = '') THEN RPRSNTV_EMAL_ADDR
						ELSE   #{rprsntvEmalAddr, jdbcType=VARCHAR}
					END	
			  	)
			  , RPRSNTV_MBL_NO = (
					CASE
						WHEN (#{rprsntvMblNo, jdbcType=VARCHAR} IS NULL OR #{rprsntvMblNo, jdbcType=VARCHAR} = '') THEN RPRSNTV_MBL_NO
						ELSE   #{rprsntvMblNo, jdbcType=VARCHAR}
					END	
			  	)
			  , UPDT_DT = CURRENT_TIMESTAMP(3)
			  , UPDT_SEQ = #{updtSeq, jdbcType=NUMERIC}
		WHERE 	1 	= 	1
		AND 		DELT_YN 	=	'N'
		AND 		(((#{compSeq, jdbcType=NUMERIC} IS NULL) OR (#{compSeq, jdbcType=NUMERIC} = 0)) OR (COMP_SEQ = #{compSeq, jdbcType=NUMERIC}))
    	AND 		(((#{compCd, jdbcType=VARCHAR} IS NULL) OR (#{compCd, jdbcType=VARCHAR} = '')) OR (COMP_CD = #{compCd, jdbcType=VARCHAR}))

mapper.insert:
    	INSERT INTO CMP_SRVC_COMP_INFO_TBL (
			CHNL_SITE_SEQ
		  , SRVC_SEQ
		  , COMP_SEQ
		  , USE_YN
		  , RGST_DT
		  , RGST_SEQ
		)
		VALUES (
			#{chnlSiteSeq, jdbcType=NUMERIC}
		  , 	#{srvcSeq, jdbcType=NUMERIC}
		  , 	#{compSeq, jdbcType=NUMERIC}
		  , ( 	
				CASE
		  			WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN 'Y'
		  			ELSE   #{useYn, jdbcType=VARCHAR}
		  		END
		    )
		  , CURRENT_TIMESTAMP(3)
		  , #{rgstSeq, jdbcType=NUMERIC}			
		)

mapper.delete:
    	DELETE 
    	FROM 	CMP_SRVC_COMP_INFO_TBL
    	WHERE 	1 	= 	1
		AND 		CHNL_SITE_SEQ = #{chnlSiteSeq, jdbcType=NUMERIC}
		AND 		SRVC_SEQ = #{srvcSeq, jdbcType=NUMERIC}
		AND 		COMP_SEQ = #{compSeq, jdbcType=NUMERIC}
